            seen.add(m.get('id'))
            if newprompt and e.get('timestamp','')>='2026-09-30T08:45':
                print('    first turn: write',u.get('cache_creation_input_tokens'),'read',u.get('cache_read_input_tokens'),'in',u.get('input_tokens'))
